/* ming-career-mini v5 - generated static bundle; source remains in Private repository */
(function(){'use strict';var encoded='';
function decodeLZW(data){
 var raw=atob(data),codes=[],i;for(i=0;i<raw.length;i+=2)codes.push(raw.charCodeAt(i)*256+raw.charCodeAt(i+1));
 var dict=[],n;for(i=0;i<256;i++)dict[i]=String.fromCharCode(i);
 var old=dict[codes[0]],out=[old];
 for(i=1;i<codes.length;i++){n=codes[i];var entry=n<dict.length?dict[n]:(n===dict.length?old+old.charAt(0):null);if(entry===null)throw new Error('asset decode failed');out.push(entry);dict.push(old+entry.charAt(0));old=entry;}
 var bytes=out.join(''),parts=[];for(i=0;i<bytes.length;i++)parts.push('%'+('0'+bytes.charCodeAt(i).toString(16)).slice(-2));return decodeURIComponent(parts.join(''));
}
try{
 var pack=JSON.parse(decodeLZW(encoded));window.MingAssets={};
 for(var key in pack.images)window.MingAssets['./assets/'+key]='data:image/svg+xml;charset=utf-8,'+encodeURIComponent(pack.images[key]);
 var style=document.createElement('style');style.textContent=pack.css;document.head.appendChild(style);
 for(var i=0;i<pack.scripts.length;i++){var script=document.createElement('script');script.text=pack.scripts[i];document.body.appendChild(script);}
}catch(err){if(window.MingBoot)window.MingBoot.fail(err.message||err);else document.body.innerHTML='载入失败，请刷新网页';}
})();